Audit this React component for performance issues:

```tsx
import moment from 'moment';
import _ from 'lodash';

const UserList = ({ users, searchTerm, onSelectUser }) => {
  const filtered = _.filter(users, u => u.name.toLowerCase().includes(searchTerm.toLowerCase()));
  const sorted = _.sortBy(filtered, 'name');

  return (
    <div>
      {sorted.map(user => (
        <div key={user.id} onClick={() => onSelectUser(user)} style={{padding:'12px',borderBottom:'1px solid #eee'}}>
          <img src={user.avatar} style={{width:'40px',height:'40px',borderRadius:'50%'}} />
          <span>{user.name}</span>
          <span>{moment(user.lastActive).fromNow()}</span>
        </div>
      ))}
    </div>
  );
};
```

The list has about 5000 users and it's super laggy when typing in search.
